/** Exact-result query corpus for checking SPARQL scope behavior across Sail implementations. */
public abstract class ScopeSafetyStoreTest {

	private static final String DATA_RESOURCE = "scope-safety/data/scope-data.trig";

	@TempDir
	protected Path dataDirectory;

	protected abstract Sail createSail(Path dataDirectory);

	@TestFactory
	public Stream<DynamicTest> scopeSafetyQueriesMatchGoldenResults() {
		Stream<DynamicTest> regularQueries = IntStream.rangeClosed(1, 50)
				.mapToObj(number -> regularQueryTest("q%02d".formatted(number)));
		Stream<DynamicTest> adversarialQueries = IntStream.rangeClosed(1, 10)
				.mapToObj(number -> adversarialQueryTest("a%02d".formatted(number)));
		return Stream.concat(regularQueries, adversarialQueries);
	}

	private DynamicTest regularQueryTest(String id) {
		return dynamicTest(id, () -> {
			String query = text("scope-safety/queries/" + id + ".rq");
			List<BindingSet> expected = readExpectedResult("scope-safety/results/" + id + ".srx").rows();
			List<BindingSet> actual = evaluate(id, query).rows();
			if ("q49".equals(id)) {
				assertThat(actual).as(id).containsExactlyElementsOf(expected);
			} else {
				assertThat(actual).as(id).containsExactlyInAnyOrderElementsOf(expected);
			}
		});
	}

	private DynamicTest adversarialQueryTest(String id) {
		return dynamicTest(id, () -> {
			String query = text("scope-safety/adversarial/queries/" + id + ".rq");
			QueryResult expected = readExpectedResult("scope-safety/adversarial/results/" + id + ".srx");
			QueryResult actual = evaluate(id, query);
			assertThat(actual.bindingNames()).as(id + " result header")
					.containsExactlyElementsOf(expected.bindingNames());
			assertThat(actual.rows()).as(id + " rows")
					.containsExactlyInAnyOrderElementsOf(expected.rows());
		});
	}

	private QueryResult evaluate(String id, String query) throws Exception {
		Path storeDirectory = Files.createDirectories(dataDirectory.resolve(id));
		SailRepository repository = new SailRepository(createSail(storeDirectory));
		try {
			repository.init();
			try (var connection = repository.getConnection(); InputStream data = resource(DATA_RESOURCE)) {
				connection.add(data, "urn:scope-safety:", RDFFormat.TRIG);
			}
			try (var connection = repository.getConnection();
					TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
				List<String> bindingNames = List.copyOf(result.getBindingNames());
				List<BindingSet> rows = new ArrayList<>();
				while (result.hasNext()) {
					BindingSet row = result.next();
					assertEveryBindingHasValue(id, row);
					rows.add(row);
				}
				return new QueryResult(bindingNames, rows);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertEveryBindingHasValue(String id, BindingSet row) {
		for (String name : row.getBindingNames()) {
			Value value = row.getValue(name);
			assertThat(value).as(id + " binding ?" + name).isNotNull();
		}
	}

	private static QueryResult readExpectedResult(String resource) throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		try (InputStream stream = resource(resource)) {
			QueryResultIO.parseTuple(stream, TupleQueryResultFormat.SPARQL, collector,
					SimpleValueFactory.getInstance());
		}
		return new QueryResult(List.copyOf(collector.getBindingNames()), List.copyOf(collector.getBindingSets()));
	}

	private static String text(String name) throws Exception {
		try (InputStream stream = resource(name)) {
			return new String(stream.readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	private static InputStream resource(String name) {
		InputStream stream = ScopeSafetyStoreTest.class.getClassLoader().getResourceAsStream(name);
		if (stream == null) {
			throw new IllegalArgumentException("Missing scope-safety resource " + name);
		}
		return stream;
	}

	private record QueryResult(List<String> bindingNames, List<BindingSet> rows) {
	}
}
